 bool bindVerifiedFirmware(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(2*CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a]||d.readResource(0x400000+a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin)||!d.protectImmutableVerified(0x400000+r.begin,0x400000+r.end,image+r.begin))return false;bound_=&d;return true;}
 bool boundTo(const ControllerDeviceState&d)const{return bound_==&d;}bool active()const{return task_.has_value();}void reset(){task_.reset();dsp_=nullptr;lcd_=nullptr;numeric_=nullptr;numericLcd_=nullptr;voices_=nullptr;voicesDsp_=nullptr;voiceInit_=nullptr;}bool start(Kind kind,uint32_t payload){if(!bound_||active()||(payload!=0xcad3&&payload!=0xcac5))return false;task_.emplace(kind,payload);return true;}Request request()const{return task_&&!dsp_&&!lcd_&&!numeric_&&!voices_&&!voiceInit_?task_->request():Request{};}bool completeService(Service s){return task_&&!dsp_&&!lcd_&&!numeric_&&!voices_&&!voiceInit_&&task_->resume(s);}bool beginDsp(ControllerDspTransferRuntime&dsp,ControllerDeviceState&d){if(bound_!=&d||!task_||dsp_||lcd_||numeric_||voices_||voiceInit_||!dsp.boundTo(d)||dsp.active())return false;auto r=task_->request();if(r.service!=Service::DspWrite||!dsp.startWrite(r.address,r.word))return false;dsp_=&dsp;return true;}
