 bool beginVoices(ControllerProgramVoicesRuntime&voices,ControllerDspTransferRuntime&dsp,ControllerDeviceState&d){if(bound_!=&d||!task_||dsp_||lcd_||numeric_||voices_||voiceInit_||!voices.boundTo(d)||voices.active()||!dsp.boundTo(d)||dsp.active()||task_->request().service!=Service::ReleaseSound||!voices.start(0,false))return false;voices_=&voices;voicesDsp_=&dsp;return true;}
